import React, { useState } from "react";
import "./App.css";
// Icons
import {
  Gamepad2, Globe, ChevronDown, User, LogOut, LayoutDashboard, UserCircle,
  X, BookOpen, Trophy, Star, TrendingUp, Zap, ChevronRight, ChevronLeft,
  WifiOff, Languages, Bot, Calculator, Atom, Monitor, Palette, Lock, Dumbbell,
  Mail, Phone, MapPin, MessageCircle, ArrowRight, Facebook, Twitter, Instagram, Youtube,
  UserPlus
} from 'lucide-react';
import { Routes, Route, useNavigate, useLocation } from "react-router-dom";

// Components
import Login from "./Login";
import Signup from "./Signup";
import Dashboard from "./components/Dashboard"; 
import Profile from "./components/Profile"; // Make sure you have this component
import Chatbot from "./components/Chatbot";
import { translations } from "./translations"; 

export default function App() {
  const [showChat, setShowChat] = useState(false);
  const [language, setLanguage] = useState("English");
  const [showLangMenu, setShowLangMenu] = useState(false);
  
  // --- AUTH STATE: Manages the logged-in user object dynamically ---
  // If null, user is not logged in. If object, user is logged in.
  const [currentUser, setCurrentUser] = useState(null); 
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [showDemo, setShowDemo] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();
  const t = translations[language]; 
  const languages = ["English", "Hindi", "Telugu"];

  // Handle Logout
  const handleLogout = () => {
     setCurrentUser(null);
     setShowProfileMenu(false);
     navigate("/"); 
  };

  // Helper to handle navigation for protected routes
  const handleProtectedClick = (destination) => {
    if (currentUser) {
      navigate(destination);
    } else {
      navigate("/login");
    }
  };

  return (
    <div className="app-root">
      {/* NAVBAR */}
      {/* */}
      <nav className="navbar">
        <div className="logo" onClick={() => navigate("/")}><Gamepad2 size={36} /> VidyaQuest</div>
        
        <div className="nav-links">
          <span onClick={() => navigate("/")}>{t.nav.home}</span>
          <span onClick={() => handleProtectedClick("/dashboard")}>{t.nav.subjects}</span>
          <span onClick={() => handleProtectedClick("/dashboard")}>{t.nav.games}</span>
          <span onClick={() => handleProtectedClick("/dashboard")}>{t.nav.leaderboard}</span>
        </div>

        <div className="auth-buttons">
          {/* Language Selector */}
          <div style={{position: 'relative'}}>
            <button className="btn-lang" onClick={() => setShowLangMenu(!showLangMenu)}>
              <Globe size={18} /> {language} <ChevronDown size={14} />
            </button>
            {showLangMenu && (
              <div className="lang-dropdown">
                {languages.map(lang => (
                  <div key={lang} className="lang-option" onClick={() => { setLanguage(lang); setShowLangMenu(false); }}>{lang}</div>
                ))}
              </div>
            )}
          </div>

          {/* DYNAMIC AUTH BUTTONS */}
          {!currentUser ? (
            <>
              <span className="signin-link" onClick={() => navigate("/login")}>{t.nav.signin}</span>
              <button className="btn-primary" onClick={() => navigate("/signup")}>{t.nav.signup}</button>
            </>
          ) : (
            <div className="user-dropdown-container">
              {/* Shows the actual logged-in user's name */}
              <button className="btn-user" onClick={() => setShowProfileMenu(!showProfileMenu)}>
                <User size={18}/> {currentUser.name} <ChevronDown size={14}/>
              </button>
              
              {showProfileMenu && (
                <div className="profile-menu">
                  <div className="menu-item" onClick={() => {navigate("/profile"); setShowProfileMenu(false);}}>
                    <UserCircle size={18}/> Profile
                  </div>
                  <div className="menu-item" onClick={() => {navigate("/dashboard"); setShowProfileMenu(false);}}>
                    <LayoutDashboard size={18}/> Dashboard
                  </div>
                  <div className="menu-item danger" onClick={handleLogout}>
                    <LogOut size={18}/> Sign Out
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </nav>

      <Routes>
        <Route path="/" element={<LandingPage t={t} onWatchDemo={() => setShowDemo(true)} />} />
        
        {/* Pass a function to Login to update currentUser state on success */}
        <Route path="/login" element={<Login onLoginSuccess={(user) => setCurrentUser(user)} />} />
        
        <Route path="/signup" element={<Signup />} />
        
        {/* Pass the currentUser object to Dashboard and Profile */}
        <Route path="/dashboard" element={<Dashboard user={currentUser} />} />
        <Route path="/profile" element={<Profile user={currentUser} />} />
      </Routes>

      {showDemo && <DemoModal onClose={() => setShowDemo(false)} />}
      
      {/* Chatbot */}
      {showChat && (
        <div className="chatbot-window">
          <div className="chatbot-header"><span>Vidya AI Tutor</span><X style={{cursor:'pointer'}} onClick={() => setShowChat(false)}/></div>
          <div className="chatbot-content"><Chatbot /></div>
        </div>
      )}
      <div className="chatbot-float-btn" onClick={() => setShowChat(!showChat)}>
        <MessageCircle size={30} />
      </div>

      <Footer t={t} navigate={navigate} />
    </div>
  );
}

// --- SUB-COMPONENTS ---

function LandingPage({ t, onWatchDemo }) {
  return (
    <>
      <header className="hero-section">
        <span className="grade-badge">{t.hero.badge}</span>
        <h1 className="hero-title">{t.hero.title1} <br /><span style={{color:'#3b82f6'}}>{t.hero.title2}</span></h1>
        <p className="hero-subtitle">{t.hero.subtitle}</p>
        <div style={{display:'flex', justifyContent:'center', gap:'1rem'}}>
          <button className="btn-primary">Start Learning</button>
          <button className="btn-secondary" onClick={onWatchDemo}>Watch Demo</button>
        </div>
         <div className="stats-row">
          <div className="stat-card"><span className="stat-num">10K+</span>{t.hero.stat1}</div>
          <div className="stat-card"><span className="stat-num">500+</span>{t.hero.stat2}</div>
          <div className="stat-card"><span className="stat-num">1000+</span>{t.hero.stat3}</div>
        </div>
      </header>
      {/* Add other landing page sections here as needed */}
    </>
  );
}

function DemoModal({ onClose }) {
  return (
    <div className="modal-overlay">
      <div className="demo-modal">
        <button className="btn-close-modal" onClick={onClose}><X size={24}/></button>
        <div className="slide-content">
          <div className="slide-icon-box" style={{background: '#10b981'}}><BookOpen size={48} color="white"/></div>
          <h2>Choose Your Subject</h2>
          <p>Pick from 8+ subjects designed for grades 6-12.</p>
        </div>
        <button className="btn-slide-nav primary" onClick={onClose}>Close Demo</button>
      </div>
    </div>
  );
}

function Footer({ t, navigate }) {
  return (
    <footer className="footer-container">
      <div className="footer-cta-bar"><button className="btn-join-banner" onClick={() => navigate("/signup")}>Join Now – Free! <ArrowRight size={20} /></button></div>
      <div className="footer">
        <div className="footer-grid">
          <div><div className="logo" style={{color:'white', marginBottom:'1.5rem'}}><Gamepad2 size={32}/> VidyaQuest</div><p>Making STEM fun.</p></div>
          <div><h4>Quick Links</h4><ul><li>Subjects</li><li>Games</li></ul></div>
          <div><h4>Contact Us</h4><ul><li>contact@vidyaquest.edu</li></ul></div>
        </div>
        <div className="copyright">{t.footer.rights}</div>
      </div>
    </footer>
  );
}
